import json,rclpy
from pathlib import Path
from rclpy.node import Node
from rclpy.qos import QoSProfile,DurabilityPolicy,ReliabilityPolicy
from rclpy.parameter import Parameter
from std_msgs.msg import String
from nav_msgs.msg import OccupancyGrid,Odometry
from tf2_msgs.msg import TFMessage
from rosidl_runtime_py.convert import message_to_ordereddict
rclpy.init();n=Node("readonly_return_map_diagnostic",parameter_overrides=[Parameter("use_sim_time",value=True)])
q=QoSProfile(depth=1,reliability=ReliabilityPolicy.RELIABLE,durability=DurabilityPolicy.TRANSIENT_LOCAL)
data={};maps={};tf={};odom={};f=Path("/tmp/p3b5_a1f_return_map_diagnostic.jsonl").open("a",buffering=1)
def state(name,msg):data[name]=json.loads(msg.data)
def grid(key,msg):maps[key]=message_to_ordereddict(msg)
def transform(name,msg):
 for x in msg.transforms:
  if x.header.frame_id.lstrip("/").endswith("map") and x.child_frame_id.lstrip("/").endswith("odom"):tf[name]=message_to_ordereddict(x)
def position(name,msg):odom[name]=message_to_ordereddict(msg)
def tick():
 if any(x.get("mode")=="RETURNING" for x in data.values()):f.write(json.dumps({"time":n.get_clock().now().nanoseconds/1e9,"battery":data,"maps":maps,"tf":tf,"odom":odom})+"\n")
for name in ("tb1","tb2"):
 n.create_subscription(String,f"/{name}/battery_state",lambda m,k=name:state(k,m),q)
 n.create_subscription(OccupancyGrid,f"/{name}/map",lambda m,k=name+"_local":grid(k,m),q)
 n.create_subscription(OccupancyGrid,f"/{name}/gateway/merge_map",lambda m,k=name+"_fused":grid(k,m),10)
 n.create_subscription(Odometry,f"/{name}/odom",lambda m,k=name:position(k,m),10)
 n.create_subscription(TFMessage,f"/{name}/tf",lambda m,k=name:transform(k,m),20)
n.create_timer(2,tick)
print("READY",flush=True)
try:rclpy.spin(n)
except KeyboardInterrupt:pass
finally:f.close();n.destroy_node();rclpy.shutdown()

